template<int N>  ap_uint<N> bit_reverse ( ap_uint<N> input ){
    #pragma HLS inline
    ap_uint<N> reversed;
    Loop_Reverse: for (int bit_i = 0; bit_i < N; bit_i++) {
        #pragma HLS UNROLL
        reversed.range(bit_i, bit_i) = input.range(N-1-bit_i, N-1-bit_i);
    }
    return reversed;
}


