            float imag_part = std::exp(-5.0 * t) * std::sin(2.0 * M_PI * 20.0 * t);
            data[b][i] = complex<float>(real_part, imag_part);
            data_gold[b][i] = complex<float>(real_part, imag_part);
        }
    }


